php foreach(range(6,12) as $grade):?><label><input class="form-check-input" type="checkbox" name="grade_scopes[]" value="<?=$grade?>"> Khối <?=$grade?></label><?php endforeach?></div><div class="form-text">Muốn chọn riêng từng khối, bỏ chọn “Tất cả khối” rồi tích các khối cần dùng.</div></div><div class="col-12"><textarea class="form-control" name="question_text" required placeholder="Nội dung câu hỏi"></textarea></div><div class="col-12"><input class="form-control" name="answer_text" placeholder="Đáp án"></div><div><button class="btn btn-primary" <?=$week?'':'disabled'?>>Thêm câu hỏi</button></div></form></div></div></div>

