="col-md-7"><select class="form-select form-select-sm" name="duplicate_mode" onchange="document.getElementById('duplicateThreshold').disabled=this.value!=='similar'"><option value="exact" <?=$duplicateMode==='exact'?'selected':''?>>Trùng chính xác</option><option value="similar" <?=$duplicateMode==='similar'?'selected':''?>>Nội dung gần giống</option></select></div><div class="col-md-5"><select id="duplicateThreshold" class="form-select form-select-sm" name="duplicate_threshold" <?=$duplicateMode!=='similar'?'disabled':''?>><?php foreach([60,70,75,80,90] as $level):?><option value="<?=$level?>" <?=$duplicateThreshold===$level?'selected':''?>>Từ <?=$level?>%</option><?php endforeach?></select></div></div><div class="d-flex gap-2 mt-2"><button type="button" class="btn btn-sm btn-outline-secondary" onclick="document.querySelectorAll('.duplicate-week').forEach(x=>x.checked=true)">Chọn tất cả</button><button class="btn btn-sm btn-primary"><i class="bi bi-search"></i> So sánh</button></div></form></div></div><?php if(!empty($_GET['check_duplicates'])):?><hr><h5 class="fw-bold mb-2">Kết quả: <?=count($duplicatePairs)?> cặp câu hỏi</h5><?php if(!$duplicatePairs):?><div class="alert alert-success py-2 mb-0">Không phát hiện câu hỏi trùng theo điều kiện đã chọn.</div><?php else:?><div class="table-responsive" style="max-height:480px"><table class="table table-sm table-bordered align-middle"><thead><tr><th style="width:90px">Giống nhau</th><th>Câu thứ nhất</th><th>Câu thứ hai</th></tr></thead><tbody><?php foreach($duplicatePairs as $pair):?><tr><td class="text-center"><span class="badge text-bg-<?=$pair['score']===100?'danger':'warning'?>"><?=$pair['score']?>%</span></td><td><div class="small text-muted"><?=e(($pair['left']['week_label']?'['.$pair['left']['week_label'].'] ':'').$pair['left']['title'])?> · <?=e($pair['left']['grade_scope']==='all'?'Tất cả khối':'Khối '.$pair['left']['grade_scope'])?> · <?=e($pair['left']['stage_name'])?></div><?=e($pair['left']['question_text'])?><div class="small text-success">Đáp án: <?=e($pair['left']['answer_text'])?></div></td><td><div class="small text-muted"><?=e(($pair['right']['week_label']?'['.$pair['right']['week_label'].'] ':'').$pair['right']['title'])?> · <?=e($pair['right']['grade_scope']==='all'?'Tất cả khối':'Khối '.$pair['right']['grade_scope'])?> · <?=e($pair['right']['stage_name'])?></div><?=e($pair['right']['question_text'])?><div class="small text-success">Đáp án: <?=e($pair['right']['answer_text'])?></div></td></tr><?php endforeach?></tbody></table></div><?php endif?><?php endif?></div></details>

