<script>document.querySelectorAll('.admin-box>h4:first-child').forEach(function(head){if(head.closest('.admin-collapse'))return;const box=head.parentElement;head.style.cursor='pointer';head.title='Bấm để mở hoặc thu gọn';const nodes=[...box.children].filter(x=>x!==head);nodes.forEach(x=>x.hidden=true);head.insertAdjacentHTML('beforeend','<span class="float-end badge text-bg-light text-primary">Mở</span>');head.addEventListener('click',function(){const opening=nodes.some(x=>x.hidden);nodes.forEach(x=>x.hidden=!opening);head.querySelector('.badge').textContent=opening?'Thu gọn':'Mở'});});const questionList=[...document.querySelectorAll('div.mt-3')].find(x=>x.querySelector(':scope>.question'));if(questionList){questionList.hidden=true;const button=document.createElement('button');button.type='button';button.className='btn btn-outline-primary w-100 mt-3';button.innerHTML='<i class="bi bi-list-check"></i> Hiện danh sách <?=count($questions)?> câu hỏi';button.onclick=function(){questionList.hidden=!questionList.hidden;button.innerHTML=questionList.hidden?'<i class="bi bi-list-check"></i> Hiện danh sách <?=count($questions)?> câu hỏi':'<i class="bi bi-chevron-up"></i> Thu gọn danh sách câu hỏi'};questionList.before(button);}</script>
<?php elseif($view==='ranking'&&$admin):?><h3 class="fw-bold">Bảng xếp hạng Olympia</h3>
