"><table class="table table-hover align-middle"><thead><tr><th>Hạng</th><th>Lớp</th><th>Tham gia/Sĩ số</th><th>Câu đúng</th><th>Tổng điểm</th><th>Bình quân</th></tr></thead><tbody><?php $pos=0;foreach($rankClasses as $r):?><tr><td><span class="badge text-bg-info fs-6"><?=++$pos?></span></td><td class="fw-bold"><?=e($r['class_name'])?></td><td><?=e($r['participants'])?>/<?=e($r['class_size'])?></td><td><?=e($r['correct'])?></td><td class="fw-bold text-primary"><?=e($r['points'])?></td><td class="fw-bold text-success"><?=e(number_format((float)$r['average'],2,',','.'))?></td></tr><?php endforeach?><?php if(!$rankClasses):?><tr><td colspan="6" class="text-center text-muted">Chưa có điểm trong khoảng tuần đã chọn.</td></tr><?php endif?></tbody></table></div></div></div></div>
<?php else:?><div class="d-flex flex-wrap align-items-center gap-3 mb-3"><div><h3 class="fw-bold mb-0"><?=e($week['title']??'Chưa có tuần Olympia')?></h3><?php if($week):?><span class="badge <?=olympia_is_open($week)?'text-bg-success':'text-bg-secondary'?>"><?=olympia_is_open($week)?'Đang mở':'Đang khóa'?></span><?php endif?></div><form class="ms-auto"><input type="hidden" name="view" value="play"><input type="hidden" name="week" value="<?=e($weekId)?>"><select class="form-select" name="class" onchange="this.form.submit()"><option value="">Chọn lớp chủ nhiệm</option><?php foreach($classes as $c):?><option value="<?=e($c['id'])?>" <?=$classId===$c['id']?'selected':''?>>Lớp <?=e($c['name'])?></option><?php endforeach?></select></form></div><?php if(!$week):?><div class="alert alert-info">Quản trị chưa tạo tuần Olympia.</div><?php elseif(!olympia_is_open($week)):?><div class="alert alert-warning">Tuần này đang khóa hoặc chưa đến thời gian mở.</div><?php elseif(!$classId):?><div class="alert alert-info">Tài khoản chưa có lớp chủ nhiệm được gán cho tuần này.</div><?php else:foreach($questions as $i=>$q):?><form method="post" class="card question p-3 mb-3"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="save_marks"><input type="hidden" name="week_id" value="<?=e($weekId)?>"><input type="hidden" name="class_id" value="<?=e($classId)?>"><input type="hidden" name="question_id" value="<?=e($q['id'])?>"><div class="stage"><?=e($q['stage_name'])?> · Câu <?=($i+1)?> · <?=e($q['points'])?> điểm</div><h5 class="fw-bold mt-1"><?=nl2br(e($q['question_text']))?></h5><details class="mb-3"><summary class="text-success fw-semibold">Hiện đáp án</summary><div class="p-2 bg-light rounded"><?=nl2br(e($q['answer_text']))?></div></details><div class="small fw-bold mb-2">Tích học sinh trả lời đúng:</div><div class="student-grid"><?php foreach($students as $s):?><label class="student-check"><input class="form-check-input me-1" type="checkbox" name="student_ids[]" value="<?=e($s['id'])?>" <?=in_array((string)$s['id'],$marks[(string)$q['id']]??[],true)?'checked':''?>> <?=e($s['name'])?></label><?php endforeach?></div><div class="mt-3"><button class="btn btn-primary"><i class="bi bi-check2-circle"></i> Lưu câu này</button></div></form><?php endforeach;endif?><?php endif?></div></main></body></html>
